const EVS = 'PetroWiki sand control techniques (S42), ISO 17824 for screens (S47), API RP 19C for gravel testing (S12 if held), field practice (S9). Generic geometry; not an OEM design.';
const GP_GLB = '/glb/SC/SC-GRAVELPACK.glb';
const sc = (o) => save({ status: 'draft', evidence_tier: 'E2', reviewers: [], system: 'SC', drawn_in_3d: false, sources: ['S42', 'S9'], revision: rev('Drop 8 seed'), hazards: [H.pressure], ...o });
const scc = (id, parent, group, name, aliases, fn, over, eng, safety, nodes, extra = {}) => sc({ id, parent, group, level: 'component', name, aliases, function: fn, tabs: { overview: over, engineering: eng, safety, evidence: EVS, ...(extra.tabs || {}) }, drawn_in_3d: !!nodes, ...(nodes ? { glb: GP_GLB, mesh_nodes: nodes } : {}), ...Object.fromEntries(Object.entries(extra).filter(([k]) => k !== 'tabs')) });

sc({ id: 'SC', level: 'system', name: 'Sand control', aliases: ['sand control', 'SC', 'sand screens', 'sand exclusion'],
  function: 'The completions that keep formation sand out of the wellbore in weak formations: gravel packs around screens, standalone screens and slotted liners, frac packs, and chemical consolidation.',
  tabs: {
    overview: 'Shale wells rarely need downhole sand control; their sand problem is proppant flowback handled at surface (FB). Weak sandstone reservoirs, offshore and in many conventional fields, do: the standard answer is a gravel pack, which public sources put at more than 90 percent of sand control completions. A screen is run across the interval and sized gravel is pumped into the annulus so the formation sand bridges on the gravel and the gravel is held by the screen. Frac packs combine a short fracture with a gravel pack; standalone screens rely on the formation sand bridging on the screen itself; resin consolidation glues the sand grains in place.',
    engineering: 'Gravel sized from the formation sand distribution; screen slot narrower than the gravel; screens designed and tested to ISO 17824. Screens or liners without gravel plug over time in most formations.',
    connections: 'Casing and perforations (CM, WL); production packer and tubing above (UC); the gravel pack service tools on the workstring (RG).',
    safety: 'Pumping pressures during the pack; heavy screen assemblies handled with the rig.',
    evidence: EVS, operations: 'Perforate, clean out, run the screen assembly with the gravel pack packer, set, pump the pack through the crossover, reverse out, pull the service tool, run the completion.',
    failure_modes: 'Screen erosion or plugging, incomplete packs leaving voids, packer or seal leaks, sand production returning.',
  }, standards: [{ standard: 'ISO 17824', edition: 'verify', paraphrase: 'Sand screen design, manufacture, and testing.', source: 'S47' }], hazards: [H.pressure, H.dropped], sources: ['S42', 'S47', 'S9'] });
sc({ id: 'SC-GRAVELPACK', parent: 'SC', group: 'gravel-pack', level: 'equipment', name: 'Cased-hole gravel pack (cut-away)', aliases: ['gravel pack', 'GP', 'cased-hole gravel pack', 'gravel pack completion', 'frac pack'],
  function: 'The screen assembly and gravel placed across a perforated interval so sand cannot enter the wellbore: gravel pack packer and crossover above, blank pipe, screen on a perforated base pipe, gravel in the annulus and perforations, sump packer and seal assembly below.',
  tabs: {
    overview: 'The sump packer is set below the interval first. The screen assembly runs on the gravel pack packer with the crossover tool and washpipe inside; the packer sets, the crossover ports open, and gravel slurry is pumped down the workstring, out through the crossover into the annulus around the screen, packing the perforations and the annulus while the carrier fluid returns through the screen and up the washpipe. The service tool and washpipe come out; the seal assembly of the completion stabs into the packer. The cut-away shows every element with the casing, cement, and formation as ghost context; a frac pack uses the same hardware with a short fracture pumped first.',
    engineering: 'Gravel sized about six times the formation sand median (a widely used rule); screen slot narrower than the smallest gravel; pack quality logged with density tools.',
    connections: 'Casing and perforations (CM, WL); production packer and tubing above (UC); workstring during the pack (RG).',
    safety: 'Pack pumped at rate and pressure against the packer; heavy assembly on the rig.',
    evidence: EVS, operations: 'Sump packer, clean-out, screen run, set, pack, reverse, pull, complete.',
    failure_modes: 'Voids from premature screenout, screen damage on running, packer leaks, fines plugging the pack.',
  }, drawn_in_3d: true, glb: GP_GLB, scene: 'SC-GRAVELPACK',
  mesh_nodes: ['SC-GRAVELPACK-GPPACKER', 'SC-GRAVELPACK-CROSSOVER', 'SC-GRAVELPACK-BLANKPIPE', 'SC-GRAVELPACK-SCREEN', 'SC-GRAVELPACK-BASEPIPE', 'SC-GRAVELPACK-GRAVEL', 'SC-GRAVELPACK-SUMPPACKER', 'SC-GRAVELPACK-SEALASSEMBLY'],
  ghost_nodes: ['SC-GRAVELPACK-CASING', 'SC-GRAVELPACK-FORMATION', 'SC-GRAVELPACK-WASHPIPE'], sources: ['S42', 'S47', 'S9'] });
scc('SC-GRAVELPACK-GPPACKER', 'SC-GRAVELPACK', 'gravel-pack', 'Gravel pack packer', ['GP packer', 'gravel pack packer', 'top packer'], 'The packer above the interval that carries the screen assembly, seals the annulus, and receives the completion seal assembly afterwards.', 'Set hydraulically from the service tool; its bore takes the crossover during the pack and the production seals after.', 'Rated for the pack pressure and the production differential.', 'Set and tested before the pack is pumped.', ['SC-GRAVELPACK-GPPACKER']);
scc('SC-GRAVELPACK-CROSSOVER', 'SC-GRAVELPACK', 'gravel-pack', 'Crossover tool and ports', ['crossover', 'crossover tool', 'service tool', 'gravel pack ports'], 'The service tool below the packer that routes slurry from the workstring out to the annulus and returns from the washpipe back up the workstring-casing annulus.', 'Positions: squeeze, circulate, reverse; shifted by picking up and setting down the workstring.', 'Per the service company tool.', 'Pressure test in each position before the pack.', ['SC-GRAVELPACK-CROSSOVER']);
scc('SC-GRAVELPACK-BLANKPIPE', 'SC-GRAVELPACK', 'gravel-pack', 'Blank pipe', ['blank', 'blank pipe', 'gravel reserve'], 'The unperforated pipe between the crossover and the screen that holds a reserve of gravel above the screen for settling.', 'Length set so the pack top stays above the screen.', 'Casing-grade pipe.', 'None beyond the string.', ['SC-GRAVELPACK-BLANKPIPE']);
scc('SC-GRAVELPACK-SCREEN', 'SC-GRAVELPACK', 'gravel-pack', 'Wire-wrapped screen', ['screen', 'wire-wrapped screen', 'WWS', 'premium screen', 'mesh screen'], 'The keystone wire wrap on ribs over the base pipe whose slot holds the gravel while letting fluid through.', 'Slot sized below the smallest gravel; premium mesh screens use woven layers for finer sand; designed and tested to ISO 17824.', 'ISO 17824.', 'Handled with protectors; erosion at high rates or with a void in the pack.', ['SC-GRAVELPACK-SCREEN'], { standards: [{ standard: 'ISO 17824', edition: 'verify', paraphrase: 'Sand screens.', source: 'S47' }], sources: ['S42', 'S47'] });
scc('SC-GRAVELPACK-BASEPIPE', 'SC-GRAVELPACK', 'gravel-pack', 'Perforated base pipe', ['base pipe', 'drilled pipe'], 'The drilled pipe under the wrap that carries the load and passes flow into the tubing.', 'Hole pattern sized for flow area; casing-grade material.', 'ISO 17824 with the screen.', 'None beyond the string.', ['SC-GRAVELPACK-BASEPIPE']);
scc('SC-GRAVELPACK-GRAVEL', 'SC-GRAVELPACK', 'gravel-pack', 'Gravel pack sand', ['gravel', 'pack sand', 'gravel pack proppant'], 'The sized sand or ceramic placed in the annulus and the perforation tunnels that filters the formation sand.', 'Sized from formation sand sieve data (about six times the median); tested like proppant for size, sphericity, and crush.', 'API RP 19C testing where held.', 'None beyond pumping.', ['SC-GRAVELPACK-GRAVEL']);
scc('SC-GRAVELPACK-SUMPPACKER', 'SC-GRAVELPACK', 'gravel-pack', 'Sump packer and seal assembly', ['sump packer', 'bottom packer', 'seal assembly (GP)'], 'The packer set below the interval before the screen is run, and the seal assembly on the screen tail that stabs into it to close the bottom of the pack.', 'Set on wireline or tubing; gives a fixed depth reference for the screen.', 'Rated for the pack pressure.', 'Set and depth-checked before the screen run.', ['SC-GRAVELPACK-SUMPPACKER', 'SC-GRAVELPACK-SEALASSEMBLY']);
scc('SC-GRAVELPACK-CONTEXT', 'SC-GRAVELPACK', 'gravel-pack', 'Casing, formation, and washpipe (context)', ['washpipe', 'gravel pack context'], 'The perforated casing and cement, the formation, and the washpipe inside the screen, shown translucent for context.', 'The washpipe returns carrier fluid during the pack and comes out with the service tool.', 'See CM records for casing and cement.', 'None.', ['SC-GRAVELPACK-CASING', 'SC-GRAVELPACK-FORMATION', 'SC-GRAVELPACK-WASHPIPE']);
sc({ id: 'SC-STANDALONESCREEN', parent: 'SC', group: 'screens', level: 'equipment', name: 'Standalone screens and slotted liners', aliases: ['standalone screen', 'SAS', 'slotted liner', 'screen only'],
  function: 'Screens or slotted liners run across the interval without gravel, relying on the formation sand bridging on the openings.',
  tabs: { overview: 'Cheaper and simpler than a gravel pack, used in openhole horizontals in well-sorted sands; public guidance warns they plug over time in most formations. Slot width is sometimes sized to the 10 percentile grain size so the coarser grains bridge.', engineering: 'Slot or mesh sized from sieve analysis; erosion and plugging are the design limits.', safety: 'Handled with protectors on the rig.', evidence: EVS, failure_modes: 'Plugging, erosion, hot spots where flow concentrates.' }, sources: ['S42', 'S47'] });
sc({ id: 'SC-CONSOLIDATION', parent: 'SC', group: 'chemical', level: 'equipment', name: 'Chemical consolidation and resin-coated gravel', aliases: ['resin consolidation', 'plastic consolidation', 'resin-coated gravel', 'chemical sand control'],
  function: 'Resin injected into the formation to bind the sand grains, or resin-coated gravel that cures in place, leaving the wellbore free of screens.',
  tabs: { overview: 'Epoxy, furan, and phenolic systems; limited today by cost and by placement over intervals longer than a few tens of feet; resin-coated gravel has shown good early results and poor longevity in public reports.', engineering: 'Placement uniformity is the design problem; permeability loss after cure.', safety: 'Chemical handling at surface.', evidence: EVS, failure_modes: 'Uneven placement, loss of permeability, sand returning as the resin degrades.' }, sources: ['S42'], hazards: [H.chem] });

